-- Generated by running the constructors of Store, ClinicDirectory and PlanDelivery at main 7507e5a (before ACCESS-00-M)
-- and dumping sqlite_master in creation order. Test fixture only: an independent record of the legacy implicit schema.
CREATE TABLE vaults (id TEXT PRIMARY KEY, auth TEXT NOT NULL, created TEXT NOT NULL, bytes INTEGER NOT NULL DEFAULT 0);
CREATE TABLE vault_protocols (vault TEXT PRIMARY KEY, minimum INTEGER NOT NULL);
CREATE TABLE records (vault TEXT NOT NULL, k TEXT NOT NULL, v TEXT, seq INTEGER NOT NULL, PRIMARY KEY (vault, k));
CREATE INDEX records_seq ON records (vault, seq);
CREATE TABLE counters (day TEXT NOT NULL, scope TEXT NOT NULL, n INTEGER NOT NULL, PRIMARY KEY (day, scope));
CREATE TABLE meta (k TEXT PRIMARY KEY, n INTEGER NOT NULL);
CREATE TABLE settings (k TEXT PRIMARY KEY, v TEXT NOT NULL);
CREATE TABLE push_subs (vault TEXT NOT NULL, device TEXT NOT NULL, sub TEXT NOT NULL, updated INTEGER NOT NULL,
        PRIMARY KEY (vault, device));
CREATE TABLE reminders (vault TEXT NOT NULL, device TEXT NOT NULL, rid TEXT NOT NULL, at INTEGER NOT NULL,
        payload TEXT NOT NULL, next_at INTEGER NOT NULL, repeats_left INTEGER NOT NULL, repeat_every INTEGER NOT NULL, sent INTEGER NOT NULL DEFAULT 0,
        PRIMARY KEY (vault, device, rid));
CREATE INDEX reminders_due ON reminders (next_at);
CREATE TABLE reminder_policies (vault TEXT PRIMARY KEY, body TEXT NOT NULL);
CREATE TABLE reminder_clients (vault TEXT NOT NULL, device TEXT NOT NULL, aware INTEGER NOT NULL,
        PRIMARY KEY (vault, device));
CREATE TABLE usage (vault TEXT NOT NULL, month TEXT NOT NULL, kind TEXT NOT NULL, calls INTEGER NOT NULL,
        usd_micro INTEGER NOT NULL, PRIMARY KEY (vault, month, kind));
CREATE TABLE spend_day (day TEXT PRIMARY KEY, usd_micro INTEGER NOT NULL);
CREATE TABLE pairs (pid TEXT PRIMARY KEY, blob TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE acks (vault TEXT NOT NULL, rid TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY (vault, rid));
CREATE TABLE device_tokens (h TEXT PRIMARY KEY, created INTEGER NOT NULL);
CREATE TABLE concierge_log (id TEXT PRIMARY KEY, vault TEXT NOT NULL, ts INTEGER NOT NULL, scenario TEXT NOT NULL,
        record TEXT NOT NULL, outcome TEXT, edit TEXT);
CREATE INDEX concierge_log_vault ON concierge_log (vault, ts);
CREATE TABLE pushed (vault TEXT NOT NULL, rid TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY (vault, rid));
CREATE TABLE vault_weeks (vault TEXT NOT NULL, week TEXT NOT NULL, PRIMARY KEY (vault, week));
CREATE TABLE pilot_members (pid TEXT PRIMARY KEY, secret_hash TEXT NOT NULL, joined TEXT NOT NULL);
CREATE TABLE pilot_weeks (pid TEXT NOT NULL, week TEXT NOT NULL, kind TEXT NOT NULL, src TEXT, body TEXT NOT NULL,
        PRIMARY KEY (pid, week, kind));
CREATE TABLE pilot_sources (code TEXT PRIMARY KEY, label TEXT NOT NULL, issued TEXT NOT NULL);
CREATE TABLE clinic_orgs (id TEXT PRIMARY KEY, name TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE clinic_members (id TEXT PRIMARY KEY, org TEXT NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL,
        token_hash TEXT NOT NULL UNIQUE, active INTEGER NOT NULL DEFAULT 1, created INTEGER NOT NULL);
CREATE INDEX clinic_members_org ON clinic_members (org);
CREATE TABLE clinic_audit (id INTEGER PRIMARY KEY AUTOINCREMENT, org TEXT NOT NULL, at INTEGER NOT NULL,
        actor TEXT NOT NULL, action TEXT NOT NULL, target TEXT);
CREATE INDEX clinic_audit_org ON clinic_audit (org, id);
CREATE TABLE plan_delivery (id TEXT PRIMARY KEY, org TEXT NOT NULL, issued_by TEXT NOT NULL,
        code_hash TEXT NOT NULL UNIQUE, plan TEXT, plan_hash TEXT NOT NULL, expires INTEGER NOT NULL,
        status TEXT NOT NULL DEFAULT 'pending', created INTEGER NOT NULL);
CREATE INDEX plan_delivery_org ON plan_delivery (org, id);
